def criterion(n, title, dimension, weight, levels, evidence, alternatives, misconceptions):
    return {'criterion_id': f'c{n}', 'title': title, 'dimension': dimension, 'weight': weight,
            'score_anchors': [{'anchor_id': f'c{n}:{i}', 'score': i, 'description': text} for i, text in enumerate(levels)],
            'required_evidence': evidence, 'acceptable_alternatives': alternatives, 'common_misconceptions': misconceptions}


